function myPow(x, n) {
  if (n === 0) return 1;
  let exp = n;
  let base = x;
  if (exp < 0) {
    base = 1 / base;
    exp = -exp;
  }
  let res = 1.0;
  for (let i = 0; i < exp; i++) {
    res *= base;
  }
  res = Math.round(res * 1e5) / 1e5;
  return Number.isInteger(res) ? Math.trunc(res) : res;
}

function myPow(x, n) {
  if (n === 0) return 1;
  let exp = n;
  let base = x;
  if (exp < 0) {
    base = 1 / base;
    exp = -exp;
  }
  let res = 1.0;
  while (exp > 0) {
    if (exp % 2 === 1) res *= base;
    base *= base;
    exp = Math.floor(exp / 2);
  }
  res = Math.round(res * 1e5) / 1e5;
  return Number.isInteger(res) ? Math.trunc(res) : res;
}

